  const SMOKE_ORB_SOURCE = `/**
 * <smoke-orb> \u2014 Self-contained smoke-particle sphere Web Component
 *
 * Attributes:
 *   color-light  \u2014 hex, lighter gradient stop   (required)
 *   color-dark   \u2014 hex, darker gradient stop     (required)
 *   size         \u2014 diameter in px, default 64
 *   label        \u2014 tooltip text on hover
 *   hero         \u2014 boolean, adds breathing aura on hover
 *
 * Usage:
 *   <smoke-orb color-light="#FCE52C" color-dark="#E0BB59"
 *              size="64" label="\u6211\u662F\u5408\u89C4\u4E3B\u7BA1" hero></smoke-orb>
 */
(function () {
  'use strict';

  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  //  Shared animation loop \u2014 one RAF for all instances
  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  var _pool = new Set();
  var _raf  = null;

  function _tick(t) {
    _pool.forEach(function (inst) { inst._render(t); });
    _raf = _pool.size ? requestAnimationFrame(_tick) : null;
  }
  function _register(inst)   { _pool.add(inst); inst._render(performance.now()); }
  function _unregister(inst) { _pool.delete(inst); }

  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  //  Helpers
  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  function hexToRgb(h) {
    return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  }

  function createSmokeSprite(color) {
    var sz = 128, c = document.createElement('canvas');
    c.width = sz; c.height = sz;
    var x = c.getContext('2d'), ctr = sz / 2, cs = color.join(',');
    var g = x.createRadialGradient(ctr, ctr, 0, ctr, ctr, sz * 0.48);
    g.addColorStop(0,    'rgba(' + cs + ',0.95)');
    g.addColorStop(0.18, 'rgba(' + cs + ',0.72)');
    g.addColorStop(0.42, 'rgba(' + cs + ',0.36)');
    g.addColorStop(0.72, 'rgba(' + cs + ',0.10)');
    g.addColorStop(1,    'rgba(' + cs + ',0)');
    x.fillStyle = g;
    x.beginPath(); x.arc(ctr, ctr, sz * 0.48, 0, Math.PI * 2); x.fill();
    return c;
  }

  function createRingSprite(color) {
    var sz = 128, c = document.createElement('canvas');
    c.width = sz; c.height = sz;
    var x = c.getContext('2d'), ctr = sz / 2, cs = color.join(',');
    var g = x.createRadialGradient(ctr, ctr, sz * 0.06, ctr, ctr, sz * 0.46);
    g.addColorStop(0,    'rgba(' + cs + ',0)');
    g.addColorStop(0.32, 'rgba(' + cs + ',0.12)');
    g.addColorStop(0.52, 'rgba(' + cs + ',0.92)');
    g.addColorStop(0.68, 'rgba(' + cs + ',0.35)');
    g.addColorStop(1,    'rgba(' + cs + ',0)');
    x.fillStyle = g;
    x.beginPath(); x.arc(ctr, ctr, sz * 0.46, 0, Math.PI * 2); x.fill();
    return c;
  }

  function fbm(x, y, z, t) {
    return Math.sin(x * 1.7 + t * 0.0008) * 0.5
         + Math.sin(y * 3.1 + t * 0.0013) * 0.25
         + Math.sin(z * 5.3 + t * 0.0019) * 0.125
         + Math.sin((x + y) * 2.3 + t * 0.0006) * 0.18;
  }

  function spawnParticle(warm) {
    var theta = Math.random() * Math.PI * 2;
    var z = Math.random() * 2 - 1;
    var shell = 0.28 + Math.pow(Math.random(), 0.42) * 0.72;
    var circ = Math.sqrt(Math.max(0, 1 - z * z));
    var life = 2200 + Math.random() * 1200;
    var isCloud = Math.random() < 0.4;
    return {
      x: Math.cos(theta) * circ * shell,
      y: z * 0.78 * shell,
      z: Math.sin(theta) * circ * shell,
      vx: (Math.random() - 0.5) * 0.07,
      vy: (Math.random() - 0.5) * 0.045,
      vz: (Math.random() - 0.5) * 0.06,
      sz: isCloud ? (0.6 + Math.random() * 0.8) : (0.25 + Math.random() * 0.45),
      rot: Math.random() * Math.PI * 2,
      spin: (Math.random() - 0.5) * 0.002,
      phase: Math.random() * Math.PI * 2,
      life: life,
      age: warm ? Math.random() * life : 0,
      alpha: isCloud ? (0.06 + Math.random() * 0.08) : (0.10 + Math.random() * 0.14),
      isCloud: isCloud
    };
  }

  function drawBlob(ctx, bx, by, br, cs, a) {
    var g = ctx.createRadialGradient(bx, by, 0, bx, by, br);
    g.addColorStop(0,    'rgba(' + cs + ',' + a + ')');
    g.addColorStop(0.45, 'rgba(' + cs + ',' + (a * 0.5) + ')');
    g.addColorStop(0.75, 'rgba(' + cs + ',' + (a * 0.12) + ')');
    g.addColorStop(1,    'rgba(' + cs + ',0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(bx, by, br, 0, Math.PI * 2); ctx.fill();
  }

  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  //  Shadow DOM template
  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  var TPL = document.createElement('template');
  TPL.innerHTML = [
    '<style>',

    // Host
    ':host{',
    '  display:inline-block;position:relative;cursor:pointer;',
    '  transition:transform .35s cubic-bezier(.34,1.56,.64,1);',
    '}',
    ':host(:hover){',
    '  z-index:100!important;transform:translateY(-14px);',
    '}',

    // Orb sphere
    '.orb{',
    '  width:100%;height:100%;border-radius:50%;overflow:hidden;position:relative;',
    '  box-shadow:0 4px 8px 0 var(--sh-a,rgba(0,0,0,.15)),',
    '             0 8px 18px 0 var(--sh-b,rgba(0,0,0,.08));',
    '  transition:transform .45s cubic-bezier(.34,1.56,.64,1),box-shadow .3s ease;',
    '}',

    // Canvas
    'canvas{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}',

    // Eyes
    '.eyes{',
    '  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;',
    '  gap:22%;pointer-events:none;z-index:4;',
    '}',
    '.eye{',
    '  position:relative;display:flex;align-items:center;justify-content:center;',
    '  width:11%;height:22%;flex-shrink:0;',
    '}',
    '.eye i{',
    '  display:block;width:100%;height:100%;border-radius:999px;',
    '  background:rgba(255,255,255,.96);font-style:normal;',
    '  box-shadow:0 0 4px rgba(255,255,255,.9),0 0 10px rgba(255,255,255,.5);',
    '  transform-origin:center center;',
    '  transition:transform .12s ease-in-out,opacity .35s cubic-bezier(.25,1,.5,1);',
    '}',
    '.eye svg{',
    '  position:absolute;width:160%;height:auto;',
    '  opacity:0;filter:drop-shadow(0 0 4px rgba(255,255,255,.6));',
    '  transition:opacity .35s cubic-bezier(.25,1,.5,1);',
    '}',
    ':host(:hover) .eye i{opacity:0}',
    ':host(:hover) .eye svg{opacity:1}',

    // Tooltip
    '.tip{',
    '  position:absolute;bottom:calc(100% + 10px);left:50%;',
    '  transform:translateX(-50%) translateY(6px);',
    '  background:#F0EDE9;color:#1A1A1A;',
    '  font-family:"PingFang SC",-apple-system,sans-serif;font-size:12px;font-weight:400;',
    '  line-height:1.5;padding:5px 10px;border-radius:8px;white-space:nowrap;',
    '  opacity:0;pointer-events:none;',
    '  box-shadow:0 2px 10px rgba(0,0,0,.1);',
    '  transition:opacity .2s ease,transform .28s cubic-bezier(.34,1.56,.64,1);',
    '}',
    '.tip::after{',
    '  content:"";position:absolute;top:100%;left:50%;transform:translateX(-50%);',
    '  border:5px solid transparent;border-top-color:#F0EDE9;',
    '}',
    '.tip:empty{display:none}',
    ':host(:hover) .tip{opacity:1;transform:translateX(-50%) translateY(0)}',

    // Hero aura
    '.aura{',
    '  display:none;position:absolute;inset:-20px;border-radius:50%;',
    '  background:radial-gradient(circle,var(--aura,rgba(255,255,255,.5)) 0%,transparent 65%);',
    '  z-index:-1;pointer-events:none;opacity:0;transition:opacity .4s ease;',
    '}',
    ':host([hero]) .aura{display:block}',
    ':host([hero]:hover) .aura{opacity:1;animation:_hg 3.2s ease-in-out infinite}',
    '@keyframes _hg{0%,100%{opacity:.38;transform:scale(.88)}50%{opacity:.85;transform:scale(1.14)}}',

    '</style>',

    '<div class="aura"></div>',
    '<div class="orb"><canvas></canvas><div class="eyes">',
    '<span class="eye"><i></i><svg viewBox="0 0 10 6" fill="none"><path d="M1 5C2.8 1.2 7.2 1.2 9 5" stroke="rgba(255,255,255,0.96)" stroke-width="2" stroke-linecap="round"/></svg></span>',
    '<span class="eye"><i></i><svg viewBox="0 0 10 6" fill="none"><path d="M1 5C2.8 1.2 7.2 1.2 9 5" stroke="rgba(255,255,255,0.96)" stroke-width="2" stroke-linecap="round"/></svg></span>',
    '</div></div>',
    '<div class="tip"></div>'
  ].join('\\n');

  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  //  SmokeOrb Custom Element
  // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
  class SmokeOrb extends HTMLElement {

    static get observedAttributes() {
      return ['color-light', 'color-dark', 'size', 'label', 'hero'];
    }

    constructor() {
      super();
      this.attachShadow({ mode: 'open' });
      this.shadowRoot.appendChild(TPL.content.cloneNode(true));

      this._canvas = this.shadowRoot.querySelector('canvas');
      this._eyes   = this.shadowRoot.querySelector('.eyes');
      this._tip    = this.shadowRoot.querySelector('.tip');
      this._orbEl  = this.shadowRoot.querySelector('.orb');
      this._auraEl = this.shadowRoot.querySelector('.aura');

      this._ctx = null;
      this._particles = [];
      this._proj = [];
      this._lt = 0;
      this._w = 64;
      this._cl = [200, 200, 200];
      this._cd = [120, 120, 120];
      this._mid = [160, 160, 160];
      this._smokeSprite = null;
      this._ringSprite  = null;
      this._returnTimer = null;

      this._onMove  = this._handleMouseMove.bind(this);
      this._onLeave = this._handleMouseLeave.bind(this);
      this._blinkTimer = null;
    }

    // \u2500\u2500 Lifecycle \u2500\u2500

    connectedCallback() {
      this._applySize();
      this._applyColors();
      this._applyLabel();
      this._initCanvas();
      this.addEventListener('mousemove',  this._onMove);
      this.addEventListener('mouseleave', this._onLeave);
      _register(this);
      this._scheduleBlink(true);
    }

    disconnectedCallback() {
      _unregister(this);
      this.removeEventListener('mousemove',  this._onMove);
      this.removeEventListener('mouseleave', this._onLeave);
      clearTimeout(this._blinkTimer);
    }

    attributeChangedCallback(name) {
      if (!this.isConnected) return;
      if (name === 'size')  { this._applySize(); this._initCanvas(); }
      if (name === 'color-light' || name === 'color-dark') { this._applyColors(); this._initCanvas(); }
      if (name === 'label') this._applyLabel();
    }

    // \u2500\u2500 Attribute \u2192 internal state \u2500\u2500

    _applySize() {
      this._w = parseInt(this.getAttribute('size'), 10) || 64;
      this.style.width  = this._w + 'px';
      this.style.height = this._w + 'px';
    }

    _applyColors() {
      var clHex = this.getAttribute('color-light') || '#C8C8C8';
      var cdHex = this.getAttribute('color-dark')  || '#787878';
      this._cl  = hexToRgb(clHex);
      this._cd  = hexToRgb(cdHex);
      this._mid = this._cl.map(function (v, i) { return Math.round((v + this._cd[i]) / 2); }.bind(this));

      // Shadow colors
      var cd = this._cd;
      this.style.setProperty('--sh-a', 'rgba(' + cd.join(',') + ',0.4)');
      this.style.setProperty('--sh-b', 'rgba(' + cd.join(',') + ',0.2)');

      // Hero aura color
      var cl = this._cl;
      this.style.setProperty('--aura', 'rgba(' + cl.join(',') + ',0.5)');

      // Rebuild sprites \u2014 use brighter colors
      var spriteBright = this._cl.map(function (v, i) { return Math.round(v * 0.8 + this._mid[i] * 0.2); }.bind(this));
      this._smokeSprite = createSmokeSprite(spriteBright);
      this._ringSprite  = createRingSprite(this._mid);
    }

    _applyLabel() {
      this._tip.textContent = this.getAttribute('label') || '';
    }

    // \u2500\u2500 Canvas init \u2500\u2500

    _initCanvas() {
      var dpr = Math.min(window.devicePixelRatio || 1, 2);
      this._canvas.width  = Math.floor(this._w * dpr);
      this._canvas.height = Math.floor(this._w * dpr);
      this._ctx = this._canvas.getContext('2d');
      this._ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      this._ctx.imageSmoothingEnabled = true;

      var count = Math.max(80, Math.floor(this._w * 3));
      this._particles = [];
      this._proj = [];
      for (var i = 0; i < count; i++) {
        this._particles.push(spawnParticle(true));
        this._proj.push({ px: 0, py: 0, s: 0, a: 0, z: 0, r: 0, cloud: false });
      }
      this._lt = 0;
    }

    // \u2500\u2500 Eye tracking \u2500\u2500

    _handleMouseMove(e) {
      clearTimeout(this._returnTimer);
      this._eyes.style.transition = '';
      var r  = this.getBoundingClientRect();
      var cx = r.left + r.width / 2;
      var cy = r.top  + r.height / 2;
      var nx = (e.clientX - cx) / (r.width / 2);
      var ny = (e.clientY - cy) / (r.height / 2);
      var maxPx = r.width * 0.15;
      var ex = (Math.max(-1, Math.min(1, nx)) * maxPx).toFixed(2);
      var ey = (Math.max(-1, Math.min(1, ny)) * maxPx).toFixed(2);
      this._eyes.style.transform = 'translate(' + ex + 'px,' + ey + 'px)';
    }

    _handleMouseLeave() {
      var eyes = this._eyes;
      eyes.style.transition = 'transform .55s cubic-bezier(.34,1.56,.64,1)';
      eyes.style.transform  = 'translate(0px,0px)';
      this._returnTimer = setTimeout(function () { eyes.style.transition = ''; }, 560);
    }

    _scheduleBlink(first) {
      var self = this;
      var delay = first ? 500 + Math.random() * 1500 : 2000 + Math.random() * 4000;
      this._blinkTimer = setTimeout(function () {
        var eyeEls = self._eyes.querySelectorAll('i');
        var doDouble = Math.random() < 0.3;

        eyeEls.forEach(function (el) { el.style.transform = 'scaleY(0.05)'; });

        setTimeout(function () {
          eyeEls.forEach(function (el) { el.style.transform = ''; });

          if (doDouble) {
            setTimeout(function () {
              eyeEls.forEach(function (el) { el.style.transform = 'scaleY(0.05)'; });
              setTimeout(function () {
                eyeEls.forEach(function (el) { el.style.transform = ''; });
                self._scheduleBlink(false);
              }, 100);
            }, 180);
          } else {
            self._scheduleBlink(false);
          }
        }, 130);
      }, delay);
    }

    // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
    //  Per-frame render
    // \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
    _render(time) {
      var ctx = this._ctx;
      if (!ctx) return;

      var w = this._w, R = w / 2, cx = R, cy = R;
      var cl = this._cl, cd = this._cd, mid = this._mid;
      var cls = cl.join(','), cds = cd.join(','), mids = mid.join(',');
      var particles = this._particles, proj = this._proj;
      var smokeSprite = this._smokeSprite, ringSprite = this._ringSprite;
      var dt = Math.min(48, this._lt ? time - this._lt : 16);
      this._lt = time;

      ctx.clearRect(0, 0, w, w);

      // 1. Semi-transparent base
      var bright = cl.map(function (v, i) { return Math.round(v * 0.7 + mid[i] * 0.3); });
      var brs = bright.join(',');
      var bg = ctx.createRadialGradient(cx + R * 0.12, cy - R * 0.1, 0, cx, cy, R);
      bg.addColorStop(0,    'rgba(' + cls + ',0.85)');
      bg.addColorStop(0.3,  'rgba(' + brs + ',0.75)');
      bg.addColorStop(0.65, 'rgba(' + mids + ',0.72)');
      bg.addColorStop(1,    'rgba(' + cds + ',0.82)');
      ctx.fillStyle = bg;
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();

      // 2. Drifting smoke clouds
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(' + Math.max(3, R * 0.22) + 'px)';

      drawBlob(ctx,
        cx - R * 0.18 + Math.sin(time * 0.0005) * R * 0.45 + Math.sin(time * 0.00031) * R * 0.15,
        cy + Math.cos(time * 0.00042) * R * 0.2,
        R, cls, 0.38);

      drawBlob(ctx,
        cx + Math.cos(time * 0.00055) * R * 0.35,
        cy + Math.sin(time * 0.00072) * R * 0.45 + Math.cos(time * 0.00028) * R * 0.12,
        R * 0.8, cls, 0.3);

      drawBlob(ctx,
        cx + Math.sin(time * 0.00038) * R * 0.25 - R * 0.2,
        cy + Math.cos(time * 0.00065) * R * 0.35 + R * 0.15,
        R * 0.6, brs, 0.25);

      drawBlob(ctx,
        cx + Math.cos(time * 0.00078) * R * 0.5,
        cy + Math.sin(time * 0.00048) * R * 0.3 - R * 0.18,
        R * 0.7, cls, 0.22);

      ctx.filter = 'none';
      ctx.restore();

      // 3. 3D particle system
      var yaw = time * 0.00035;
      var pitch = Math.sin(time * 0.0002) * 0.18;
      var cY = Math.cos(yaw), sY = Math.sin(yaw);
      var cP = Math.cos(pitch), sP = Math.sin(pitch);

      for (var i = 0; i < particles.length; i++) {
        var p = particles[i];
        p.age += dt;
        if (p.age > p.life) { particles[i] = spawnParticle(false); p = particles[i]; }

        var t = p.age / p.life;
        var fade = t < 0.5
          ? 0.5 * Math.pow(2, 20 * t - 10)
          : 1 - 0.5 * Math.pow(2, -20 * t + 10);
        fade = Math.sin(Math.PI * Math.sqrt(fade));

        var turb = fbm(p.x * 3, p.y * 3, p.z * 3, time + p.phase * 1000);
        var sw = time * 0.0003 + p.phase + turb * 0.4;
        p.x += (p.vx + turb * 0.012) * dt * 0.001;
        p.y += (p.vy + Math.sin(time * 0.001 + p.phase) * 0.008) * dt * 0.001;
        p.z += (p.vz + turb * 0.01) * dt * 0.001;
        p.rot += p.spin * dt;

        var sx = p.x * Math.cos(sw) - p.z * Math.sin(sw) * 0.3;
        var sz = p.z * Math.cos(sw) + p.x * Math.sin(sw) * 0.3;
        var rx = sx * cY + sz * sY;
        var rz = sz * cY - sx * sY;
        var ry = p.y * cP - rz * sP;
        var rz2 = rz * cP + p.y * sP;
        var depth = 0.45 + (rz2 + 1) * 0.35;

        proj[i].px    = cx + rx * R * 0.82;
        proj[i].py    = cy + ry * R * 0.88 + Math.sin(time * 0.0012 + p.phase) * R * 0.04;
        proj[i].s     = R * p.sz * (0.7 + fade * 0.8) * depth * 0.7;
        proj[i].a     = p.alpha * fade * (0.5 + depth * 0.6);
        proj[i].z     = rz2;
        proj[i].r     = p.rot + yaw * 0.5;
        proj[i].cloud = p.isCloud;
      }

      proj.sort(function (a, b) { return a.z - b.z; });

      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (var j = 0; j < proj.length; j++) {
        var it = proj[j];
        if (it.a < 0.005) continue;
        ctx.save();
        ctx.globalAlpha = it.a;
        ctx.translate(it.px, it.py);
        ctx.rotate(it.r);
        ctx.scale(1, 0.75);
        ctx.drawImage(it.cloud ? smokeSprite : ringSprite, -it.s, -it.s, it.s * 2, it.s * 2);
        ctx.restore();
      }
      ctx.restore();

      // 4. Bloom pass
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(' + Math.max(2, R * 0.1) + 'px)';
      for (var k = 0; k < proj.length; k++) {
        var bi = proj[k];
        if (bi.a < 0.04 || bi.cloud) continue;
        ctx.save();
        ctx.globalAlpha = bi.a * 0.18;
        ctx.translate(bi.px, bi.py);
        ctx.drawImage(smokeSprite, -bi.s * 2.2, -bi.s * 2.2, bi.s * 4.4, bi.s * 4.4);
        ctx.restore();
      }
      ctx.filter = 'none';
      ctx.restore();

      // 5. Glass rim
      ctx.globalAlpha = 1;
      ctx.globalCompositeOperation = 'source-over';

      var shell = ctx.createRadialGradient(cx + R * 0.08, cy - R * 0.12, R * 0.25, cx, cy, R);
      shell.addColorStop(0,    'rgba(255,255,255,0.06)');
      shell.addColorStop(0.55, 'rgba(255,255,255,0.01)');
      shell.addColorStop(0.78, 'rgba(255,255,255,0.14)');
      shell.addColorStop(0.92, 'rgba(255,255,255,0.32)');
      shell.addColorStop(1,    'rgba(255,255,255,0.45)');
      ctx.strokeStyle = shell;
      ctx.lineWidth = Math.max(1.5, R * 0.1);
      ctx.beginPath();
      ctx.arc(cx, cy, R - Math.max(1, R * 0.05), 0, Math.PI * 2);
      ctx.stroke();

      ctx.strokeStyle = 'rgba(255,255,255,0.18)';
      ctx.lineWidth = Math.max(0.5, R * 0.03);
      ctx.beginPath();
      ctx.arc(cx, cy, R - Math.max(0.5, R * 0.03), Math.PI * 0.1, Math.PI * 1.5);
      ctx.stroke();

      // 6. Specular highlights
      ctx.save();
      ctx.filter = 'blur(' + Math.max(2, R * 0.1) + 'px)';

      ctx.fillStyle = 'rgba(255,255,255,0.22)';
      ctx.beginPath();
      ctx.ellipse(cx + R * 0.24, cy - R * 0.28, R * 0.11, R * 0.26, -0.42, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      ctx.beginPath();
      ctx.ellipse(cx - R * 0.32, cy + R * 0.18, R * 0.08, R * 0.18, 0.25, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.beginPath();
      ctx.ellipse(cx - R * 0.05, cy - R * 0.72, R * 0.35, R * 0.08, 0.08, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }
  }

  customElements.define('smoke-orb', SmokeOrb);
})();
`;
